// @scenario MCP-71 MCP-69
// @tier ui
//
// MCP Hub 工具列表页(`/mcp-tools`)的两件事:
//   MCP-71  复选框与批量操作栏的**三态** —— 无 `platform_mcp:edit` 时整列隐藏
//   MCP-69  「风险等级」「调用所需角色」两列的**展示正确性**
//
// ── 这两条为什么此前写不了 ──────────────────────────────────────────────────
// 该页原本**只有 1 个 data-testid**(`mcp-hub-overcapacity-banner`)。
// 按 `CLAUDE.md:61`「缺 testid 就去前端补并提 MR」,我方补了 9 个
// (被测仓 MR !56,已合入 `588802059`),这两条才有了抓手。
//
// ── ⚠️ MCP-71 的方向是**改过的**,读之前先知道来龙去脉 ──────────────────────
// 需求方手工测出 GL#552:「无编辑权限的用户仍能勾选复选框,勾完批量按钮全是灰的」。
// 我最初按「应隐藏**或**置灰」写。但在写用例期间产品已经修了 ——
//   `93f4c7b17 fix(web/mcp-hub): 无 platform_mcp:edit 时隐藏工具复选框与批量操作栏`
// 走的是 `docs/permission-spec.md:263` 三态里的**「整块无关→隐藏」**,
// 而不是置灰。所以本条从「等一个缺陷」改成**「守住这个修复」**:
//   → 断言无权角色的复选框**不在 DOM 里**(`count() === 0`),
//     **不是** `disabled=true`。断成置灰会永远红,而红的是用例不是产品。
//
// ── 判据出处(spec 明文,不是自己发明的)────────────────────────────────────
// `docs/permission-spec.md:275`(§13 前端三态 + 菜单投影):
//   > 三态:整块无关→**隐藏** / 能看不能改→**置灰+原因** / 兜底→**后端 403**。
//   > **杜绝「能编辑、点保存才报错」。**
// 分裂点是 **`platform_mcp:edit`**,仅 super_admin / platform_admin 持有
// (GL#552 的 issue 正文里逐角色实测过 5 个账号)。
//
// ── ⚠️ 「枚举一遍」不是口号 ────────────────────────────────────────────────
// GL#552 的形态是:**同页大部分控件都做对了、唯独两处复选框漏了同一道判断**
// (启停开关、编辑、删除、批量按钮都已正确置灰)。
// 所以本条把该页的写操作控件**逐个**验一遍,不挑代表性控件 ——
// 挑一个验正好可能挑中做对的那个。
//
// ⚠️ 本条会造临时账号并登录。登录是 (账号+IP) 限流大户,
//    别和整轮 API 域跑背靠背执行(见 docs/case-ledger.md §0.40)。
import { test, expect } from '@playwright/test'
import { sel, routes, hintFor } from '../../support/selectors'
import { requireCreds, login, expectLoggedIn, creds } from '../../support/auth'
import {
  apiLogin, apiGet, apiPost, apiDelete, internalTools,
  anyTeam, makeTeamMember, dropFromTeam,
} from '../../support/mcpapi'

/** 造一个指定平台角色的临时账号。失败抛错,不返回半个对象。 */
async function makeIdentity(adminTok: string, role: string) {
  const user = `uag-qa-ui-hub-${role}-${Date.now()}-${Math.floor(Math.random() * 9999)}`
  const pass = `Qa#UiHub-${Math.floor(Math.random() * 99999)}9a`
  const r = await apiPost(adminTok, '/admin-users', { username: user, password: pass, platform_role: role })
  const id = r.body?.data?.id
  if (!id) throw new Error(`造 ${role} 身份失败(HTTP ${r.status}):${JSON.stringify(r.body).slice(0, 200)}`)
  return { id, user, pass }
}

/**
 * 按 source_type 各挑一个工具名回来:`{ internal, upstream? }`。
 *
 * ⚠️ 为什么要按**行**挑、而不是勾「分组全选」:
 *    页面是**按服务器分组**渲染的(`index.tsx:900-925`,每组一张表)。
 *    勾分组全选时,选中的是**那一组**;而「批量删除是否可用」取决于
 *    **选中项**的成分(`selectionAllInternal`),不是环境里有没有非内置工具。
 *    按行挑能让两侧都**确定**:内置那一行必然置灰、上游那一行必然可用。
 */
async function pickToolNames(adminTok: string): Promise<{ internal?: string; upstream?: string }> {
  // ⚠️ `apiGet` 返回的是**已解析的 JSON 本身**,没有 `.body` 包封
  //    (`apiPost` / `apiPut` 才返回 `{status, body}`)。照着 apiPost 的形状写会拿到
  //    undefined,而 undefined 在这里表现成「环境里没有内置工具」—— 一个指向环境的假象。
  const d = await apiGet(adminTok, '/mcp-tools?page=1&page_size=200')
  const rows: Array<{ name?: string; source_type?: string }> = d?.data ?? []
  return {
    internal: rows.find((t) => t.source_type === 'internal')?.name,
    upstream: rows.find((t) => t.source_type && t.source_type !== 'internal')?.name,
  }
}

/**
 * 打开 MCP Hub 工具页并等到列表真的渲染出来(不是骨架屏)。
 *
 * ⚠️ `.first()` 不是偷懒 —— 页面**按服务器分组**,每组一张表、各带一份表头,
 *    于是 `mcp-hub-col-risk` 会命中**多个**元素。不加 `.first()` 时 Playwright
 *    报 `strict mode violation`,而且报的是「未命中」的提示语,极易误读成前端改名了。
 *    这里要的语义是「**列表成形了**」,任何一组的表头出现都足以证明,所以取第一个。
 * ⚠️ 2026-08-29 实测:**只要环境里存在任何一个上游**,整个 mcp ui 套件的 4 条
 *    **全部**红在这一行上 —— 此前它们能绿,只是因为环境里恰好一个上游都没有。
 *    → 判据:**「当前环境只有一组/一页/一条」这种前提,不写出来就等于交给运气。**
 */
async function openHub(page: any) {
  await page.goto(routes.mcpHub)
  // 等到「风险等级」列头出现 —— 它对所有角色都渲染,是列表已成形的可靠信号。
  // ⚠️ 不能等复选框:无权角色下它**根本不存在**,那样会把正确行为等成超时。
  await expect(page.locator(sel.mcpHubList.colRisk).first(), hintFor(sel.mcpHubList.colRisk))
    .toBeVisible({ timeout: 25_000 })
}

test.describe('MCP-71 MCP Hub 复选框与批量栏的三态', () => {
  let adminTok = ''
  let team: { teamId: string; ownerId: string } | null = null
  const trash: string[] = []
  const inTeam: string[] = []      // 放进过团队的人,收尾要先摘再删

  test.beforeAll(async () => {
    if (!creds.password) return
    adminTok = await apiLogin(creds.user, creds.password)
    team = await anyTeam(adminTok)
  })

  test.afterAll(async () => {
    // 先从团队里摘掉再删账号 —— 反了会留下指向已删账号的 membership。
    for (const id of inTeam) if (team) await dropFromTeam(adminTok, team.teamId, id)
    for (const id of trash) {
      const code = await apiDelete(adminTok, `/admin-users/${id}`)
      if (code < 200 || code >= 300) console.warn(`临时账号 ${id} 删除返回 ${code},需人工清理`)
    }
  })

  test.beforeEach(() => requireCreds(test))

  test('超管:复选框与批量栏**都在**,且勾选后批量按钮可用 @smoke', async ({ page }) => {
    // 正面基线。没有它,下面「无权角色看不到」可能只是 testid 写错了 —— 那是假绿。
    await login(page)
    await expectLoggedIn(page)
    await openHub(page)

    // 复选框列存在(超管有 platform_mcp:edit)。⚠️ `.first()`:每个分组一份表头。
    await expect(page.locator(sel.mcpHubList.selectGroup).first(), hintFor(sel.mcpHubList.selectGroup))
      .toBeVisible()

    const names = await pickToolNames(adminTok)
    expect(names.internal, '前提:环境里至少有一个内置工具(否则下面没得勾)').toBeTruthy()

    // ── ① 勾一个**内置**工具 ────────────────────────────────────────────────
    await page.locator(sel.mcpHubList.selectRow(names.internal!)).click()

    // 启用 / 停用:对超管**永远**可用 —— 它们不看选中项的类型(`:602`/`:616`)
    for (const s of [sel.mcpHubList.batchEnable, sel.mcpHubList.batchDisable]) {
      const btn = page.locator(s)
      await expect(btn, hintFor(s)).toBeVisible()
      await expect(btn, `超管的批量按钮不该是禁用态:${s}`).toBeEnabled()
    }

    // ⚠️ 批量删除**不是**「超管就一定可用」,它取决于**选中了什么**。
    // 产品规则(`web/src/routes/mcp-tools/index.tsx:428-432, 640-643`):
    //     selectionAllInternal = 选中项非空 && 每一项 source_type === "internal"
    //     disabled = … || selectionAllInternal
    // 内置工具**删不掉**(行内菜单同样的判断在 `:1197`),
    // 所以选中的全是内置工具时按钮置灰,并给出原因 `hub.internal_undeletable` ——
    // 正是 permission-spec §13 三态里的「能看不能改 → 置灰 + **原因**」。
    const del = page.locator(sel.mcpHubList.batchDelete)
    await expect(del, hintFor(sel.mcpHubList.batchDelete)).toBeVisible()
    await expect(del, '★选中的是内置工具 → 批量删除应当置灰(内置工具删不掉)').toBeDisabled()
    await expect(del, '★置灰还不够,必须给出原因(permission-spec §13:置灰 + 原因)')
      .toHaveAttribute('aria-disabled', 'true')

    // ── ② ★镜像面:勾一个**上游**工具 → 删除必须**可用** ─────────────────────
    // 没有这一支,①「置灰」这条断言在一个**永远把删除置灰**的实现下同样成立 ——
    // 那是恒真的第 4 种形态(只验否定面)。
    await page.locator(sel.mcpHubList.clearSelection).click()
    if (names.upstream) {
      await page.locator(sel.mcpHubList.selectRow(names.upstream)).click()
      await expect(del, '★★选中的是上游工具 → 批量删除应当**可用**(它删得掉)').toBeEnabled()
      await page.locator(sel.mcpHubList.clearSelection).click()
    } else {
      // 不是静默跳过:说清楚这一次**没有**验到镜像面,以及为什么。
      test.info().annotations.push({
        type: 'partial',
        description: '本次环境里没有上游工具,「删除可用」那一侧未验到 —— ' +
          '①的置灰断言因此不构成「产品区分了两类工具」的证据。' +
          '要补验:注册一个可达上游(见 api/mcp/upstream-sync-success-lifecycle.sh)后重跑。',
      })
    }
  })

  // 三个无 platform_mcp:edit 的角色逐个验 —— GL#552 的 issue 里这三个都实测复现过。
  for (const role of ['auditor', 'none'] as const) {
    test(`${role}:复选框与批量栏**整块不在 DOM 里**(三态之「隐藏」)`, async ({ page }) => {
      const u = await makeIdentity(adminTok, role)
      trash.push(u.id)

      // ⚠️ `none` 不进团队就**进不了控制台** —— 落地页是「你的账号还不属于任何团队」
      //    拦截页,页面上任何业务 testid 都不存在。实测踩过:症状是
      //    「mcp-hub-col-risk 找不到」,**看起来像前端删了 testid**,
      //    其实是这个人根本没走进 MCP Hub。
      //    平台角色(auditor 等)是团队无关的,不需要这一步。
      if (role === 'none') {
        test.skip(!team, '环境里找不到带 owner_id 的团队,造不出「有团队的普通成员」')
        expect(await makeTeamMember(adminTok, team!.teamId, team!.ownerId, u.id),
          `把 ${u.user} 加进团队 ${team!.teamId} 失败(名单是全量替换,漏掉持有资产的现有成员会 409)`)
          .toBe(true)
        inTeam.push(u.id)
      }

      await page.context().clearCookies()
      await login(page, u.user, u.pass)
      await expectLoggedIn(page)
      await openHub(page)

      // ★ 枚举该页的写操作控件,逐个断言「不在 DOM 里」——
      //   不是 disabled(GL#552 修成了隐藏,断成置灰会永远红)
      const mustBeAbsent: Array<[string, string]> = [
        ['分组全选复选框', sel.mcpHubList.selectGroup],
        ['批量启用', sel.mcpHubList.batchEnable],
        ['批量停用', sel.mcpHubList.batchDisable],
        ['批量删除', sel.mcpHubList.batchDelete],
      ]
      for (const [name, s] of mustBeAbsent) {
        expect(await page.locator(s).count(),
          `${role} 无 platform_mcp:edit,${name} 应当整块隐藏(不在 DOM 里),实测存在`)
          .toBe(0)
      }

      // ★ 逐行复选框也要枚举 —— GL#552 的形态正是「表头做对了、行内漏了」(或反之)
      const tools = await internalTools(adminTok)
      const sample = tools.slice(0, 3).map((t) => t.name).filter(Boolean)
      expect(sample.length, '前提:环境里至少有几个内置工具可供逐行检查').toBeGreaterThan(0)
      for (const name of sample) {
        expect(await page.locator(sel.mcpHubList.selectRow(name)).count(),
          `${role} 的第「${name}」行复选框也应当不在 DOM 里(表头与行内必须同门)`)
          .toBe(0)
      }

      // 正面对照:页面本身是渲染出来的(列头在),排除「整页没加载」造成的假绿
      // ⚠️ `.first()`:分组渲染 ⇒ 表头有多份。上面几条用的是 `.count()`,多元素无妨;
      //    这里是 `toBeVisible()`,不加会 strict mode violation。
      await expect(page.locator(sel.mcpHubList.colRisk).first(), '页面已渲染(上面的「不存在」不是整页空白)')
        .toBeVisible()
    })
  }
})

test.describe('MCP-69 「风险等级」「调用所需角色」两列的展示正确性', () => {
  let adminTok = ''

  test.beforeAll(async () => {
    if (!creds.password) return
    adminTok = await apiLogin(creds.user, creds.password)
  })
  test.beforeEach(() => requireCreds(test))

  test('两列都渲染，且「调用所需角色」列的取值与 API 的 tags 一致', async ({ page }) => {
    await login(page)
    await expectLoggedIn(page)
    await openHub(page)

    // ⚠️ `.first()`:页面按服务器分组,每组一张表各带一份表头 —— 不加会 strict mode violation。
    await expect(page.locator(sel.mcpHubList.colRisk).first(), hintFor(sel.mcpHubList.colRisk)).toBeVisible()
    await expect(page.locator(sel.mcpHubList.colRole).first(), hintFor(sel.mcpHubList.colRole)).toBeVisible()

    // ★ 真值来源是 API 的 tags —— 页面这一列展示的就是它。
    //   带标签的工具(实测 create_provider=平台管理员 / delete_team=超级管理员)
    //   的标签文本必须出现在页面上;不带标签的不该凭空多出角色文本。
    const tools = await internalTools(adminTok)
    const tagged = tools.filter((t) => (t.tags?.length ?? 0) > 0)
    expect(tagged.length, '前提:环境里至少有一个带治理标签的内置工具(否则这一列没内容可验)')
      .toBeGreaterThan(0)

    const pageText = await page.locator('body').innerText()
    for (const t of tagged) {
      for (const tag of t.tags ?? []) {
        expect(pageText,
          `工具 ${t.name} 的治理标签「${tag}」应当出现在「调用所需角色」列里`)
          .toContain(tag)
      }
    }
  })
})

